def list_search_queries(status=None, query_hash=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0499000" if __import__("os").path.isdir("./environment_mix/0499000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Validate filters
    allowed_status = {"received", "searching", "completed", "failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "status must be one of received, searching, completed, failed")
    if query_hash is not None and not isinstance(query_hash, str):
        return _err("VALIDATION_ERROR", "query_hash must be a string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError("datetime must be a string")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(ss)

    try:
        dt_after = _parse_dt(created_after)
    except Exception:
        return _err("VALIDATION_ERROR", "created_after must be ISO 8601 date-time")
    try:
        dt_before = _parse_dt(created_before)
    except Exception:
        return _err("VALIDATION_ERROR", "created_before must be ISO 8601 date-time")

    # Decode cursor
    start_idx = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or not isinstance(payload.get("offset"), int):
                return _err("VALIDATION_ERROR", "Invalid cursor")
            start_idx = payload["offset"]
            if start_idx < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    rows = _load("search_queries.json")
    if not isinstance(rows, list):
        rows = []

    def _row_dt(row, key):
        v = row.get(key)
        if not isinstance(v, str):
            return None
        try:
            return _parse_dt(v)
        except Exception:
            return None

    # Filter
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if query_hash is not None and r.get("query_hash") != query_hash:
            continue
        cdt = _row_dt(r, "created_at")
        if dt_after is not None and cdt is not None and cdt < dt_after:
            continue
        if dt_before is not None and cdt is not None and cdt >= dt_before:
            continue
        if dt_after is not None and cdt is None:
            continue
        if dt_before is not None and cdt is None:
            continue
        out.append(r)

    # Sort most recent first by created_at then id
    def _sort_key(r):
        c = r.get("created_at")
        return (c if isinstance(c, str) else "", r.get("id") if isinstance(r.get("id"), str) else "")
    out.sort(key=_sort_key, reverse=True)

    total = len(out)
    if start_idx > total:
        start_idx = total
    page = out[start_idx:start_idx + limit]

    next_cursor = None
    has_more = start_idx + limit < total
    if has_more:
        payload = json.dumps({"v": 1, "offset": start_idx + limit}, ensure_ascii=False).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _ = time.time() - t0
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }

def get_search_query(id, **_extra):
    import json, os, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0499000" if __import__("os").path.isdir("./environment_mix/0499000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    rows = _load("search_queries.json")
    if not isinstance(rows, list):
        rows = []

    row = None
    for r in rows:
        if isinstance(r, dict) and r.get("id") == id:
            row = r
            break
    if row is None:
        return _err("NOT_FOUND", "search_query not found", id=id)

    _ = time.time() - t0
    return {"search_query": row}

def list_pdf_candidates(search_query_id, status=None, source_host=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0499000" if __import__("os").path.isdir("./environment_mix/0499000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "list_pdf_candidates"

    # Simple service dynamics: per-call request logging + basic rate limit.
    # Since schema did not declare an audit collection, we maintain a vendor-internal log file.
    _REQ_FILE = "_request_log.json"
    def _log(status_code, ok, message=None):
        latency_ms = int((time.time() - _t0) * 1000)
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        logs = _load(_REQ_FILE)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{len(logs)+1}",
            "endpoint": endpoint,
            "status": "ok" if ok else "error",
            "status_code": status_code,
            "message": message,
            "latency_ms": latency_ms,
            "timestamp": ts
        })
        _save(_REQ_FILE, logs)

    def _rate_limit_check():
        logs = _load(_REQ_FILE)
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window_s = 60
        max_per_window = 120  # conservative local limit
        cnt = 0
        for r in reversed(logs[-2000:]):
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (now - dt).total_seconds() <= window_s:
                cnt += 1
        if cnt >= max_per_window:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=window_s, limit=max_per_window)
        return None

    rl = _rate_limit_check()
    if rl is not None:
        _log(429, False, rl["error"]["message"])
        return rl

    # Validate inputs
    if not isinstance(search_query_id, str) or not search_query_id:
        e = _err("VALIDATION_ERROR", "search_query_id must be a non-empty string.", field="search_query_id")
        _log(400, False, e["error"]["message"])
        return e

    allowed_status = {"discovered", "filtered", "fetch_scheduled", "fetched", "fetch_failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            e = _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=sorted(list(allowed_status)))
            _log(400, False, e["error"]["message"])
            return e

    if source_host is not None and (not isinstance(source_host, str) or source_host == ""):
        e = _err("VALIDATION_ERROR", "source_host must be a non-empty string when provided.", field="source_host")
        _log(400, False, e["error"]["message"])
        return e

    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        e = _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
        _log(400, False, e["error"]["message"])
        return e
    if limit < 1 or limit > 500:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 500.", field="limit")
        _log(400, False, e["error"]["message"])
        return e

    # Cursor: opaque base10 integer offset encoded as string: "o:<offset>"
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.startswith("o:"):
            e = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            _log(400, False, e["error"]["message"])
            return e
        try:
            offset = int(cursor.split(":", 1)[1])
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            _log(400, False, e["error"]["message"])
            return e
        if offset < 0:
            e = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            _log(400, False, e["error"]["message"])
            return e

    # Validate search_query exists
    sqs = _load("search_queries.json")
    if not isinstance(sqs, list):
        sqs = []
    if not any(isinstance(r, dict) and r.get("id") == search_query_id for r in sqs):
        e = _err("NOT_FOUND", "search_query_id not found.", search_query_id=search_query_id)
        _log(404, False, e["error"]["message"])
        return e

    cands = _load("pdf_candidates.json")
    if not isinstance(cands, list):
        cands = []

    rows = []
    for r in cands:
        if not isinstance(r, dict):
            continue
        if r.get("search_query_id") != search_query_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if source_host is not None and r.get("source_host") != source_host:
            continue
        rows.append(r)

    # Sort by rank ascending, then id for stability
    def _rank_key(x):
        rk = x.get("rank")
        try:
            rk = int(rk)
        except Exception:
            rk = 10**12
        return (rk, str(x.get("id", "")))
    rows.sort(key=_rank_key)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"o:{next_offset}" if has_more else None

    resp = {
        "object": "list",
        "data": page,
        "search_query_id": search_query_id,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor
    }
    _log(200, True)
    return resp

def get_pdf_document(id, **_extra):
