    _REQ_FILE = "_request_log.json"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status_code, ok, message=None, credential_id=None):
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load(_REQ_FILE)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{len(logs) + 1}",
                "endpoint": endpoint,
                "status": "ok" if ok else "error",
                "status_code": int(status_code),
                "message": message,
                "latency_ms": latency_ms,
                "timestamp": _utcnow_z(),
                "credential_id": credential_id,
            }
        )
        _save(_REQ_FILE, logs)

    def _rate_limit_check():
        logs = _load(_REQ_FILE)
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window_s = 60
        max_per_window = 240
        cnt = 0
        for r in reversed(logs[-5000:]):
            dt = _parse_ts(r.get("timestamp"))
            if dt is None:
                continue
            if (now - dt).total_seconds() <= window_s:
                cnt += 1
                if cnt > max_per_window:
                    return _err(
                        "RATE_LIMIT",
                        "Rate limit exceeded. Please retry later.",
                        window_seconds=window_s,
                        limit=max_per_window,
                    )
            else:
                break
        return None

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        rl = _rate_limit_check()
        if rl is not None:
            _log(429, False, rl["error"]["message"])
            return rl
        err = _err("VALIDATION_ERROR", "id must be a non-empty string.", id=id)
        _log(400, False, err["error"]["message"])
        return err

    rl = _rate_limit_check()
    if rl is not None:
        _log(429, False, rl["error"]["message"])
        return rl

    # Load documents; accept either a list-of-rows file or {"rows": [...]} shape.
    docs_raw = _load("pdf_documents.json")
    if isinstance(docs_raw, dict) and isinstance(docs_raw.get("rows"), list):
        docs = docs_raw.get("rows")
    elif isinstance(docs_raw, list):
        docs = docs_raw
    else:
        docs = []

    row = None
    for r in docs:
        if isinstance(r, dict) and r.get("id") == id:
            row = r
            break

    if row is None:
        err = _err("NOT_FOUND", "pdf_document not found.", id=id)
        _log(404, False, err["error"]["message"])
        return err

    resp = {"pdf_document": row}
    _log(200, True)
    return resp

